function Stat({icon:Icon,value,label,foot}:any){return <div className="stat"><div className="stat-top"><span className="stat-icon"><Icon size={19}/></span><ArrowUpRight size={15}/></div><div className="stat-number">{value}</div><h4>{label}</h4><p>{foot}</p></div>}
function MoreDots(){return <span className="more-dots">•••</span>}
